use rvn_core::{Engine,Renderer,renderer::SceneRenderBatch,random::RandomState,types::SpriteState};
use rvn_parser::{Value,Statement,Position,Transition,Hotspot,ParsedProgram};
use std::sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}};
#[derive(Clone,Default)]struct Host{batches:Arc<Mutex<Vec<SceneRenderBatch>>>,reject:Arc<AtomicBool>}
impl Renderer for Host{
 fn validate_scene_batch(&self,_:&SceneRenderBatch)->Result<(),String>{if self.reject.load(Ordering::SeqCst){Err("fixture preflight failure".into())}else{Ok(())}}
 fn publish_scene_batch(&mut self,b:SceneRenderBatch){self.batches.lock().unwrap().push(b);}
 fn supports_accessibility(&self)->bool{true}fn validate_accessibility_speech(&self,_:&rvn_ui::accessibility::SpeechRequest)->Result<(),String>{Ok(())}
 fn supports_composable_motion(&self)->bool{true}fn supports_video(&self)->bool{true}fn supports_layered_characters(&self)->bool{true}fn supports_programmable_ui(&self)->bool{true}
 fn supports_custom_canvas(&self)->bool{true}
 fn update_videos(&mut self,_:&[rvn_core::video::VideoView])->Result<(),String>{Ok(())}fn update_motions(&mut self,_:&[rvn_core::motion::MotionView])->Result<(),String>{Ok(())}fn update_interfaces(&mut self,_:&[rvn_ui::programmable::ScreenView])->Result<(),String>{Ok(())}fn update_layered_characters(&mut self,_:&[rvn_core::composition::LayeredView])->Result<(),String>{Ok(())}
 fn set_background(&mut self,_:&str,_:&Transition){}fn show_sprite(&mut self,_:&str,_:Option<&str>,_:&Position,_:&Transition,_:Option<&SpriteState>){}fn hide_sprite(&mut self,_:&str,_:&Transition,_:&SpriteState){}fn move_sprite(&mut self,_:&str,_:&Position,_:&Transition,_:&SpriteState){}fn show_dialogue(&mut self,_:Option<&str>,_:&str){}fn show_choice(&mut self,_:&[String])->usize{0}fn show_imagemap(&mut self,_:&str,_:Option<&str>,_:&[Hotspot])->usize{0}fn music_play(&mut self,_:&str,_:&Transition,_:Option<&str>){}fn music_stop(&mut self,_:&Transition){}fn music_set_volume(&mut self,_:f32){}fn sfx_play(&mut self,_:&str,_:&Transition){}fn sfx_stop(&mut self,_:&str,_:&Transition){}
}
fn program(source:&str,path:&str)->ParsedProgram{let mut p=rvn_parser::parse_program(source).unwrap();let path=Some(std::path::PathBuf::from(path));p.sources[0].path=path.clone();for o in &mut p.origins{o.source=path.clone();}p}
fn engine(p:ParsedProgram)->Engine<Host>{let mut e=Engine::from_program(p,Host::default(),16).unwrap();e.state.random=RandomState::seeded(4);e}
fn expected(draws:usize)->RandomState{let mut r=RandomState::seeded(4);for _ in 0..draws{r.integer(1,1).unwrap();}r}
fn state(e:&Engine<Host>)->serde_json::Value{serde_json::to_value(&e.state).unwrap()}
fn finish(e:&mut Engine<Host>,s:&mut rvn_core::engine::DebugSession){for _ in 0..128{if e.debug_step(s,rvn_core::editor_debugger::StepKind::Continue).unwrap().0==rvn_core::engine::DebugProgress::Complete{return;}}panic!("debug operation did not finish");}
fn tables(e:&mut Engine<Host>){e.text_resources_mut().publish(rvn_core::string_table::StringTableAsset{id:"asset:Table".into(),namespace:"VN".into(),entries:[(" raw key ".into(),rvn_core::string_table::StringTableEntry{source:"Ready".into(),developer_notes:String::new(),metadata:Default::default()})].into()}).unwrap();}
fn rejects_task_payload(p:&ParsedProgram,save:&rvn_core::save::consumer_checkpoint::Save15,kind:&str,with_tables:bool){let mut forged=serde_json::to_value(save).unwrap();let tasks=forged["debugger"]["trace"]["pending"]["tasks"].as_array_mut().unwrap();let task=tasks.iter_mut().find(|task|task["kind"]==kind).expect("actual pending consumer phase");task["data"]=serde_json::json!({"body":["random(1,1)"],"scope":"forged"});let mut cold=engine(p.clone());if with_tables{tables(&mut cold);}let before=state(&cold);let epoch=cold.runtime_epoch();let batches=cold.renderer.batches.lock().unwrap().len();let error=cold.restore_save15(p,rvn_core::save::consumer_checkpoint::Save15::decode(&forged.to_string()).unwrap()).err().unwrap();assert!(error.to_string().contains("cursor"),"must refuse canonical task data, got {error}");assert_eq!(state(&cold),before);assert_eq!(cold.runtime_epoch(),epoch);assert_eq!(cold.renderer.batches.lock().unwrap().len(),batches);}
fn choice(e:&mut Engine<Host>)->Vec<String>{match e.step_until_interaction().unwrap().unwrap(){rvn_core::Interaction::Choice{options}=>options,x=>panic!("expected actual Choice, got {x:?}")}}
#[test]fn real_choice_scene_and_legacy_cold_save_preserve_typed_labels_indices_and_selected_child_only(){
 let authored=include_str!("fixtures/consume_v2_choice.rvn");for source in [authored.to_string(),authored.replace("scene label start","label start")]{let p=program(&source,"C:/choice/original.rvn");let relocated=program(&source,"D:/choice/relocated.rvn");let mut e=engine(p.clone());tables(&mut e);assert_eq!(choice(&mut e),vec!["A Ready","B Ready"]);assert_eq!(e.active_choice_indices().unwrap(),vec![0,2]);assert_eq!(e.state.random,expected(4));let before=state(&e);let batches=e.renderer.batches.lock().unwrap().len();assert_eq!(choice(&mut e),vec!["A Ready","B Ready"]);assert_eq!(state(&e),before);assert_eq!(e.renderer.batches.lock().unwrap().len(),batches);let save=e.capture_save15(&p,None,1,"Choice ports".into()).unwrap();let mut cold=engine(relocated.clone());tables(&mut cold);cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap();assert_eq!(choice(&mut cold),vec!["A Ready","B Ready"]);assert_eq!(cold.state.random,expected(4));cold.submit_choice(1).unwrap();cold.step_silent().unwrap();assert_eq!(cold.state.vars["result"],Value::Int(2));assert_eq!(cold.state.random,expected(5));assert!(cold.rollback());assert_eq!(choice(&mut cold),vec!["A Ready","B Ready"]);assert_eq!(cold.state.random,expected(4));cold.submit_choice(0).unwrap();cold.step_silent().unwrap();assert_eq!(cold.state.vars["result"],Value::Int(1));assert_eq!(cold.state.random,expected(5));}
}
#[test]fn choice_condition_and_label_debugger_cold_restore_keep_real_option_phase_without_replay(){
 use rvn_core::editor_debugger as w;let source=include_str!("fixtures/consume_v2_choice.rvn");for function in ["condition","caption"]{let p=program(source,"C:/choice/debug.rvn");let relocated=program(source,"D:/choice/debug.rvn");let prepared=rvn_core::program::PreparedNarrative::from_parsed(p.clone()).unwrap();let pc=prepared.script.iter().position(|s|matches!(s,Statement::Function{name,..}if name==function)).unwrap();let bp=w::Breakpoint{position:prepared.position(pc),site:Some(w::Site{function:Some(function.into()),route:vec![w::Route::Statement(1)],depth:1,statement:true}),enabled:true};let mut e=engine(p.clone());tables(&mut e);e.enter_label("start").unwrap();let before=state(&e);let mut session=e.debug_begin(rvn_core::engine::DebugOperation::Statement,vec![bp]).unwrap();assert_eq!(e.debug_step(&mut session,w::StepKind::Continue).unwrap().0,rvn_core::engine::DebugProgress::Stopped);assert_eq!(state(&e),before);let save=e.capture_save15(&p,Some(&session),1,"Choice actual phase".into()).unwrap();rejects_task_payload(&p,&save,if function=="caption"{"consumer_choice_label"}else{"consumer_choice_selected"},true);let mut cold=engine(relocated.clone());tables(&mut cold);let mut resumed=cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap().unwrap();finish(&mut cold,&mut resumed);assert_eq!(choice(&mut cold),vec!["A Ready","B Ready"]);assert_eq!(cold.state.random,expected(4));cold.submit_choice(1).unwrap();cold.step_silent().unwrap();assert_eq!(cold.state.vars["result"],Value::Int(2));assert_eq!(cold.state.random,expected(5));}}
#[test]fn for_and_foreach_use_once_only_bounds_collection_and_real_iteration_consumers_in_scene_function_and_legacy(){
 let source=include_str!("fixtures/consume_v2_for.rvn");for legacy in [false,true]{let source=if legacy{source.replace("scene label start\nlocal total=0","label start\nset total=0").replace("local total=total+item","set total=total+item")}else{source.to_string()};let mut e=engine(program(&source,"C:/for/story.rvn"));e.step_silent().unwrap();assert_eq!(e.state.vars["result"],Value::Int(15));if !legacy{assert_eq!(e.state.scene_execution.as_ref().unwrap().active.as_ref().unwrap().locals["total"],Value::Int(15));assert!(!e.state.vars.contains_key("total"));}else{assert_eq!(e.state.vars["total"],Value::Int(15));}assert_eq!(e.state.random,expected(22));}}
#[test]fn nested_for_break_leaves_each_and_while_without_rechecking_effectful_consumer_headers(){
 let source=include_str!("fixtures/consume_v2_for_break.rvn");for legacy in [false,true]{let source=if legacy{source.replace("scene label start\nlocal total=0","label start\nset total=0").replace("local total=total+item","set total=total+item")}else{source.to_string()};let mut e=engine(program(&source,"C:/for/break.rvn"));e.step_silent().unwrap();let total=if legacy{&e.state.vars["total"]}else{&e.state.scene_execution.as_ref().unwrap().active.as_ref().unwrap().locals["total"]};assert_eq!(total,&Value::Int(3));assert_eq!(e.state.random,expected(6));}}
#[test]fn for_mid_iteration_cold_save15_restores_real_temporaries_and_remaining_iteration_only(){
 let authored=include_str!("fixtures/consume_v2_for.rvn");let (definitions,story)=authored.split_once("scene label start").unwrap();let source=format!("{definitions}scene label start{}",story.replace("local total=total+item}","local total=total+item}\n\"item [item]\""));let p=program(&source,"C:/for/mid.rvn");let relocated=program(&source,"D:/for/mid.rvn");let mut e=engine(p.clone());assert!(matches!(e.step_until_interaction().unwrap(),Some(rvn_core::Interaction::Dialogue{text,..})if text=="item 1"));assert_eq!(e.state.random,expected(5));let temps=e.state.scene_execution.as_ref().unwrap().active.as_ref().unwrap().temporaries.clone();assert!(temps.values().any(|v|matches!(v,Value::List(items)if items==&vec![Value::Int(1),Value::Int(2)])));let save=e.capture_save15(&p,None,1,"real iteration".into()).unwrap();let mut cold=engine(relocated.clone());cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap();assert_eq!(cold.state.scene_execution.as_ref().unwrap().active.as_ref().unwrap().temporaries,temps);assert_eq!(cold.state.random,expected(5));for expected_item in [2,2,3,3,4]{cold.advance_dialogue().unwrap();assert!(matches!(cold.step_until_interaction().unwrap(),Some(rvn_core::Interaction::Dialogue{text,..})if text==format!("item {expected_item}")));}cold.advance_dialogue().unwrap();cold.step_silent().unwrap();assert_eq!(cold.state.vars["result"],Value::Int(15));assert_eq!(cold.state.random,expected(28));
}
#[test]fn for_root_bounds_and_function_iterator_cursor_cold_debugger_restore_do_not_repeat_inputs(){
 use rvn_core::editor_debugger as w;let authored=include_str!("fixtures/consume_v2_for.rvn");for function_case in [false,true]{let source=if function_case{format!("{}\nscene label start\nset result=caller()\n\"done\"",authored.split("scene label start").next().unwrap())}else{authored.to_string()};let p=program(&source,"C:/for/debug.rvn");let relocated=program(&source,"D:/for/debug.rvn");let prepared=rvn_core::program::PreparedNarrative::from_parsed(p.clone()).unwrap();let pc=prepared.script.iter().position(|s|matches!(s,Statement::Function{name,..}if name=="last")).unwrap();let bp=w::Breakpoint{position:prepared.position(pc),site:Some(w::Site{function:Some("last".into()),route:vec![w::Route::Statement(1)],depth:if function_case{2}else{1},statement:true}),enabled:true};let mut e=engine(p.clone());e.enter_label("start").unwrap();if !function_case{while !matches!(e.peek_statement(),Some(Statement::ScheduledConsumer{consumer,..})if consumer=="range"){e.preview_step_statement().unwrap();}}let before=state(&e);let mut session=e.debug_begin(rvn_core::engine::DebugOperation::Statement,vec![bp]).unwrap();assert_eq!(e.debug_step(&mut session,w::StepKind::Continue).unwrap().0,rvn_core::engine::DebugProgress::Stopped);assert_eq!(state(&e),before);let save=e.capture_save15(&p,Some(&session),1,"actual iterator phase".into()).unwrap();let mut cold=engine(relocated.clone());let mut resumed=cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap().unwrap();finish(&mut cold,&mut resumed);if function_case{assert_eq!(cold.state.vars["result"],Value::Int(15));assert_eq!(cold.state.random,expected(11));}else{assert_eq!(cold.state.random,expected(2));cold.step_silent().unwrap();assert_eq!(cold.state.vars["result"],Value::Int(15));assert_eq!(cold.state.random,expected(22));}}
}
#[test]fn choice_gather_selection_and_restore_renderer_failure_are_atomic_and_bad_owner_never_falls_back(){
 let source=include_str!("fixtures/consume_v2_choice.rvn");let p=program(source,"C:/choice/refusal.rvn");let mut e=engine(p.clone());tables(&mut e);e.enter_label("start").unwrap();let before=state(&e);let batches=e.renderer.batches.lock().unwrap().len();e.renderer.reject.store(true,Ordering::SeqCst);assert!(e.step_until_interaction().is_err());assert_eq!(state(&e),before);assert_eq!(e.renderer.batches.lock().unwrap().len(),batches);e.renderer.reject.store(false,Ordering::SeqCst);choice(&mut e);let before=state(&e);e.renderer.reject.store(true,Ordering::SeqCst);assert!(e.submit_choice(1).is_err());assert_eq!(state(&e),before);e.renderer.reject.store(false,Ordering::SeqCst);let save=e.capture_save15(&p,None,1,"owned Choice".into()).unwrap();let mut forged=serde_json::to_value(&save).unwrap();forged["story"]["base"]["scene_execution"]["display"]["consumer_choice"]["owner"]=serde_json::json!({"kind":"game"});let mut cold=engine(p.clone());tables(&mut cold);let before=state(&cold);let epoch=cold.runtime_epoch();assert!(cold.restore_save15(&p,rvn_core::save::consumer_checkpoint::Save15::decode(&forged.to_string()).unwrap()).is_err());assert_eq!(state(&cold),before);assert_eq!(cold.runtime_epoch(),epoch);cold.renderer.reject.store(true,Ordering::SeqCst);assert!(cold.restore_save15(&p,save.clone()).is_err());assert_eq!(state(&cold),before);cold.renderer.reject.store(false,Ordering::SeqCst);cold.restore_save15(&p,save).unwrap();assert_eq!(choice(&mut cold),vec!["A Ready","B Ready"]);assert_eq!(cold.state.random,expected(4));
}
#[test]fn hidden_choice_never_reads_label_or_child_and_empty_range_never_gathers_body(){
 let source=r#"function hidden(){local draw=random(1,1) return false} scene label start flow.consume_v2("scene:start","choice"){capture "draw"=random(1,1) choice {"hidden [1/0]" if hidden()=>{flow.consume_v2("scene:start","bad"){capture "draw"=random(1,1) set result=1/0}}}} "done""#;let mut e=engine(program(source,"C:/choice/hidden.rvn"));assert!(matches!(e.step_until_interaction().unwrap(),Some(rvn_core::Interaction::Dialogue{text,..})if text=="done"));assert_eq!(e.state.random,expected(3));assert!(!e.state.vars.contains_key("result"));
 let source=r#"scene label start flow.consume_v2("scene:start","range"){capture "draw"=random(1,1) flow.for_loop(i,2,1){flow.consume_v2("scene:start","bad"){capture "draw"=random(1,1) set result=1/0}}} flow.consume_v2("scene:start","each"){capture "draw"=random(1,1) for item in []{flow.consume_v2("scene:start","bad2"){set result=1/0}}} "done""#;let mut e=engine(program(source,"C:/for/empty.rvn"));e.step_silent().unwrap();assert_eq!(e.state.random,expected(2));assert!(!e.state.vars.contains_key("result"));
}

#[test]fn lexical_iterator_task_cursor_restores_after_collection_call_without_replaying_it(){
 use rvn_core::editor_debugger as w;let source=r#"function values(){local draw=random(1,1) return [2,3]} function caller(){local sum=0 flow.consume_v2("fn:caller","each"){capture "header"=random(1,1) for item in values(){flow.consume_v2("fn:caller","item"){capture "draw"=random(1,1) local sum=sum+item}}} return sum} scene label start set result=caller()"#;let p=program(source,"C:/for/lexical.rvn");let relocated=program(source,"D:/for/lexical.rvn");let prepared=rvn_core::program::PreparedNarrative::from_parsed(p.clone()).unwrap();let pc=prepared.script.iter().position(|s|matches!(s,Statement::Function{name,..}if name=="values")).unwrap();let bp=w::Breakpoint{position:prepared.position(pc),site:Some(w::Site{function:Some("values".into()),route:vec![w::Route::Statement(1)],depth:2,statement:true}),enabled:true};let mut e=engine(p.clone());e.enter_label("start").unwrap();let before=state(&e);let mut session=e.debug_begin(rvn_core::engine::DebugOperation::Statement,vec![bp]).unwrap();assert_eq!(e.debug_step(&mut session,w::StepKind::Continue).unwrap().0,rvn_core::engine::DebugProgress::Stopped);assert_eq!(state(&e),before);let save=e.capture_save15(&p,Some(&session),1,"iterator cursor".into()).unwrap();assert!(save.encode().unwrap().contains("consumer_iteration"));rejects_task_payload(&p,&save,"consumer_iteration",false);let mut cold=engine(relocated.clone());let mut resumed=cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap().unwrap();finish(&mut cold,&mut resumed);assert_eq!(cold.state.vars["result"],Value::Int(5));assert_eq!(cold.state.random,expected(4));
}
#[test]fn reached_choice_in_real_loop_regathers_only_on_each_new_visit_and_uses_real_input(){
 let source=r#"function caption(){local draw=random(1,1) return "port"} scene label start for item in [1,2]{flow.consume_v2("scene:start","choice"){capture "draw"=random(1,1) choice {"[item]:[caption()]"=>{flow.consume_v2("scene:start","picked"){capture "draw"=random(1,1) set result=item}} "hidden [1/0]" if false=>{set result=1/0}}}}"#;let mut e=engine(program(source,"C:/choice/loop.rvn"));assert_eq!(choice(&mut e),vec!["1:port"]);assert_eq!(e.state.random,expected(2));e.submit_selection(0).unwrap();assert_eq!(choice(&mut e),vec!["2:port"]);assert_eq!(e.state.vars["result"],Value::Int(1));assert_eq!(e.state.random,expected(5));let before=state(&e);assert_eq!(choice(&mut e),vec!["2:port"]);assert_eq!(state(&e),before);e.submit_selection(0).unwrap();e.step_silent().unwrap();assert_eq!(e.state.vars["result"],Value::Int(2));assert_eq!(e.state.random,expected(6));
}
#[test]fn retained_typed_labels_resolve_new_table_revision_and_locale_without_producer_replay(){
 use std::collections::HashMap;use rvn_core::locale::{LocaleManager,LocaleTable};let source=include_str!("fixtures/consume_v2_choice.rvn");let mut e=engine(program(source,"C:/choice/locale.rvn"));tables(&mut e);assert_eq!(choice(&mut e),vec!["A Ready","B Ready"]);let before=state(&e);e.text_resources_mut().publish(rvn_core::string_table::StringTableAsset{id:"asset:Table".into(),namespace:"VN".into(),entries:[(" raw key ".into(),rvn_core::string_table::StringTableEntry{source:"Updated".into(),developer_notes:String::new(),metadata:Default::default()})].into()}).unwrap();assert_eq!(choice(&mut e),vec!["A Updated","B Updated"]);assert_eq!(state(&e),before);let catalogs=HashMap::from([("en".into(),LocaleTable{lang:"en".into(),strings:HashMap::new()}.into()),("fr".into(),LocaleTable{lang:"fr".into(),strings:HashMap::from([("A [caption()]".into(),"Alpha [caption()]".into()),("B [caption()]".into(),"Beta [caption()]".into())])}.into())]);e.locale=Some(LocaleManager::from_frozen_catalogs("en","fr",vec!["en".into(),"fr".into()],catalogs).unwrap());assert_eq!(choice(&mut e),vec!["Alpha Updated","Beta Updated"]);assert_eq!(state(&e),before);e.locale.as_mut().unwrap().set_language("en").unwrap();assert_eq!(choice(&mut e),vec!["A Updated","B Updated"]);assert_eq!(state(&e),before);
}
#[test]fn invalid_iteration_inputs_refuse_header_effects_and_authored_child_consumers_have_exact_sources(){
 for body in ["for item in 7 {set result=1}","flow.for_loop(i,0,100000) {set result=1}","flow.for_loop(i,true,3) {set result=1}"]{let source=format!("scene label start flow.consume_v2(\"scene:start\",\"bad\"){{capture \"draw\"=random(1,1) {body}}}");let mut e=engine(program(&source,"C:/for/refusal.rvn"));e.enter_label("start").unwrap();let before=state(&e);let batches=e.renderer.batches.lock().unwrap().len();assert!(e.preview_step_statement().is_err());assert_eq!(state(&e),before);assert_eq!(e.renderer.batches.lock().unwrap().len(),batches);}
 for (source,path) in [(include_str!("fixtures/consume_v2_for.rvn"),"C:/for/provenance.rvn"),(include_str!("fixtures/consume_v2_choice.rvn"),"C:/choice/provenance.rvn")]{for legacy in [false,true]{let text=if legacy{source.replace("scene label start\nlocal total=0","label start\nset total=0").replace("local total=total+item","set total=total+item").replace("scene label start","label start")}else{source.to_string()};let p=program(&text,path);let map=rvn_core::debugger_provenance::SourceMap::from_program(&p).unwrap();let prepared=if legacy{let e=engine(p.clone());e.script.clone()}else{rvn_core::program::PreparedNarrative::from_parsed(p.clone()).unwrap().script};for(pc,s)in prepared.iter().enumerate(){if matches!(s,Statement::ScheduledConsumer{..}){let origin=&map.origins[pc];assert_eq!(origin.source.as_ref().unwrap().to_string_lossy(),path);assert!(origin.span.as_ref().is_some_and(|span|span.end<=text.len()&&span.start<span.end));assert!(matches!(origin.route.first(),Some(rvn_core::program::AstRoutePart::Root{..})));}}}}
}

#[test]fn debugger_choice_uses_actual_visible_source_option_and_rejects_stale_visit(){
 let source=r#"scene label start flow.consume_v2("scene:start","choice"){capture "draw"=random(1,1) choice {"hidden" if false=>{set result=0} "first"=>{flow.consume_v2("scene:start","first"){capture "draw"=random(1,1) set result=1}} "second"=>{set result=2}}}"#;let mut e=engine(program(source,"C:/choice/input.rvn"));assert_eq!(choice(&mut e),vec!["first","second"]);let input=e.preview_input_source().unwrap();assert_eq!(input.choice_indices,vec![1,2]);let mut session=e.debug_begin(rvn_core::engine::DebugOperation::Choice{source:input.clone(),index:1},vec![]).unwrap();finish(&mut e,&mut session);assert!(!e.accepts_preview_input_source(&input));e.step_silent().unwrap();assert_eq!(e.state.vars["result"],Value::Int(1));assert_eq!(e.state.random,expected(2));let before=state(&e);assert!(e.debug_begin(rvn_core::engine::DebugOperation::Choice{source:input,index:2},vec![]).is_err());assert_eq!(state(&e),before);
}
#[test]fn legacy_nested_iterator_cold_save_has_real_child_origins_and_no_repeat_bounds_or_collection(){
 let authored=include_str!("fixtures/consume_v2_for.rvn");let (definitions,story)=authored.split_once("scene label start").unwrap();let source=format!("{definitions}label start{}",story.replace("local total=0","set total=0").replace("local total=total+item}","set total=total+item}\n\"item [item]\""));let p=program(&source,"C:/for/legacy-mid.rvn");let relocated=program(&source,"D:/for/legacy-mid.rvn");let mut e=engine(p.clone());assert!(matches!(e.step_until_interaction().unwrap(),Some(rvn_core::Interaction::Dialogue{text,..})if text=="item 1"));assert_eq!(e.state.random,expected(5));let save=e.capture_save15(&p,None,1,"legacy iterator".into()).unwrap();let mut cold=engine(relocated.clone());cold.restore_save15(&relocated,rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap()).unwrap();assert_eq!(cold.state.random,expected(5));for item in [2,2,3,3,4]{cold.advance_dialogue().unwrap();assert!(matches!(cold.step_until_interaction().unwrap(),Some(rvn_core::Interaction::Dialogue{text,..})if text==format!("item {item}")));}cold.advance_dialogue().unwrap();cold.step_silent().unwrap();assert_eq!(cold.state.vars["result"],Value::Int(15));assert_eq!(cold.state.random,expected(28));
}
